"""Camera lifecycle and explicitly separate barrier inventory."""

from __future__ import annotations

import hashlib
import time
from dataclasses import dataclass

from .provider import Client, ProviderError
from .restream import Go2Rtc


@dataclass(slots=True)
class Camera:
    checkpoint_id: str
    name: str
    channel: str
    stream_name: str
    refreshed_at: float = 0
    refresh_due_at: float = 0
    last_error: str | None = None


@dataclass(frozen=True, slots=True)
class Barrier:
    barrier_id: str
    name: str
    acs_id: str


class Bridge:
    def __init__(
        self, client: Client, restream: Go2Rtc, refresh_seconds: int = 45
    ) -> None:
        self.client = client
        self.restream = restream
        self.refresh_seconds = refresh_seconds
        self.cameras: dict[str, Camera] = {}
        self.barriers: dict[str, Barrier] = {}

    def discover(self) -> list[Camera]:
        cameras: dict[str, Camera] = {}
        barriers: dict[str, Barrier] = {}
        for obj in self.client.inventory():
            object_id = obj.get("id")
            if object_id is None:
                continue
            for checkpoint in self.client.checkpoints(str(object_id)):
                raw_id = checkpoint.get("id")
                if raw_id is None:
                    continue
                checkpoint_id = str(raw_id)
                name = str(checkpoint.get("name") or "Checkpoint")
                channel = checkpoint.get("channel")
                if channel:
                    cameras[checkpoint_id] = Camera(
                        checkpoint_id,
                        name,
                        str(channel),
                        self.restream.stable_name(checkpoint_id),
                    )
                acs_id = checkpoint.get("acsId")
                if acs_id:
                    digest = hashlib.sha256(checkpoint_id.encode()).hexdigest()[:12]
                    barrier_id = f"md_parking_access_{digest}"
                    barriers[barrier_id] = Barrier(barrier_id, name, str(acs_id))
        self.cameras = cameras
        self.barriers = barriers
        return list(cameras.values())

    def open_barrier(self, barrier_id: str) -> object:
        barrier = self.barriers.get(barrier_id)
        if barrier is None:
            raise KeyError("unknown barrier")
        return self.client.access(barrier.acs_id)

    def refresh(self, checkpoint_id: str) -> Camera:
        camera = self.cameras[checkpoint_id]
        try:
            source = self.client.stream(camera.channel)
            self.restream.replace_source(camera.stream_name, source)
        except ProviderError as exc:
            camera.last_error = exc.safe_code
            raise
        except Exception:
            camera.last_error = "restream_failed"
            raise
        camera.refreshed_at = time.time()
        camera.refresh_due_at = time.monotonic() + self.refresh_seconds
        camera.last_error = None
        return camera

    def refresh_due(self) -> list[Camera]:
        now = time.monotonic()
        updated: list[Camera] = []
        first_failure: Exception | None = None
        for camera in self.cameras.values():
            if camera.refresh_due_at <= now:
                try:
                    updated.append(self.refresh(camera.checkpoint_id))
                except Exception as exc:
                    if first_failure is None:
                        first_failure = exc
        if first_failure is not None:
            raise first_failure
        return updated

    def camera_status(self) -> list[dict]:
        now = time.time()
        return [
            {
                "id": camera.stream_name,
                "available": camera.refreshed_at > 0 and camera.last_error is None,
                "source_age_seconds": (
                    int(max(0, now - camera.refreshed_at))
                    if camera.refreshed_at
                    else None
                ),
                "last_error": camera.last_error,
            }
            for camera in self.cameras.values()
        ]
